def expected_max_sharpe(sr_std, n_trials):
    em = 0.5772  # Euler-Mascheroni constant
    return sr_std * (
        (1 - em) * norm.ppf(1 - 1/n_trials)
        + em * norm.ppf(1 - 1/(n_trials * np.e))
    )

def deflated_sharpe_ratio(sr_hat, returns, n_obs, n_trials, sr_std):
    sr_benchmark = expected_max_sharpe(sr_std, n_trials)
    return probabilistic_sharpe_ratio(sr_hat, sr_benchmark, returns, n_obs)
